CREATE TABLE departments (id INT, dept_name VARCHAR(50));
INSERT INTO departments VALUES (1, 'AI'), (2, 'Backend'), (3, 'HR');

-- Departments that have at least one employee
SELECT dept_name 
FROM departments 
WHERE dept_name IN (SELECT DISTINCT department FROM employees);

CREATE TABLE projects (id INT, dept_name VARCHAR(50), budget INT);
INSERT INTO projects VALUES (10, 'AI', 100000);

-- Find employees in departments that have projects
SELECT e.name, e.department
FROM employees e
WHERE EXISTS (
    SELECT 1 FROM projects p WHERE p.dept_name = e.department
);

-- Semi-join using EXISTS avoids duplicate customer rows without DISTINCT
CREATE TABLE customers (id INT, name VARCHAR(50));
CREATE TABLE orders (id INT, customer_id INT);
INSERT INTO customers VALUES (1, 'Alice'), (2, 'Bob');
INSERT INTO orders VALUES (101, 1), (102, 1);

SELECT c.name FROM customers c 
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);

SELECT MAX(salary) AS second_highest 
FROM employees 
WHERE salary < (SELECT MAX(salary) FROM employees);
